// RH-LIB v2 (2026-11-01) — funciones puras compartidas. Sin red, sin secretos.
const RH = (function () {
  const esNum = (v) => typeof v === 'number' && Number.isFinite(v);
  const esEnteroNoNeg = (v) => esNum(v) && v >= 0 && Math.floor(v) === v;
  const esListaTxt = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
  const unicos = (a) => Array.from(new Set(a));

  // Lee usage de Responses API sin sustituir ausencias por cero.
  function leerUsage(usage) {
    const r = { tokens_entrada: null, tokens_cache: null, tokens_salida: null, tokens_razonamiento: null, cache_informada: false, razonamiento_informado: false, usage_presente: false, errores: [] };
    if (!usage || typeof usage !== 'object') { r.errores.push('usage ausente'); return r; }
    r.usage_presente = true;
    if (esEnteroNoNeg(usage.input_tokens)) r.tokens_entrada = usage.input_tokens; else r.errores.push('usage.input_tokens ausente o inválido');
    if (esEnteroNoNeg(usage.output_tokens)) r.tokens_salida = usage.output_tokens; else r.errores.push('usage.output_tokens ausente o inválido');
    const det = usage.input_tokens_details;
    if (det && det.cached_tokens !== undefined && det.cached_tokens !== null) {
      if (!esEnteroNoNeg(det.cached_tokens)) r.errores.push('cached_tokens inválido (' + String(det.cached_tokens) + ')');
      else {
        r.tokens_cache = det.cached_tokens; r.cache_informada = true;
        if (r.tokens_entrada !== null && det.cached_tokens > r.tokens_entrada) r.errores.push('Incoherente: cached_tokens (' + det.cached_tokens + ') > input_tokens (' + r.tokens_entrada + ')');
      }
    }
    const od = usage.output_tokens_details;
    if (od && od.reasoning_tokens !== undefined && od.reasoning_tokens !== null) {
      if (!esEnteroNoNeg(od.reasoning_tokens)) r.errores.push('reasoning_tokens inválido');
      else {
        r.tokens_razonamiento = od.reasoning_tokens; r.razonamiento_informado = true;
        if (r.tokens_salida !== null && od.reasoning_tokens > r.tokens_salida) r.errores.push('Incoherente: reasoning_tokens > output_tokens');
      }
    }
    return r;
  }

  // costo_tokens_usd = ((in - cache) * t_in + cache * t_cache + out * t_out) / 1e6
  // El razonamiento ya está dentro de output_tokens: no se suma otra vez.
  function costoTokens(u, t) {
    if (!t || !(t.entrada > 0) || !(t.salida > 0) || !(t.cache >= 0)) return { costo: null, tipo: 'desconocido', motivo: 'Tarifas incompletas: costo no calculado.' };
    if (u.errores.length || u.tokens_entrada === null || u.tokens_salida === null) return { costo: null, tipo: 'desconocido', motivo: 'Consumo desconocido o incoherente: ' + (u.errores.join('; ') || 'usage incompleto') + '. No se presume costo cero.' };
    const cache = u.cache_informada ? u.tokens_cache : 0;
    const costo = ((u.tokens_entrada - cache) * t.entrada + cache * t.cache + u.tokens_salida * t.salida) / 1000000;
    if (u.cache_informada) return { costo: costo, tipo: 'calculado', motivo: 'Tokens medidos por usage de la API; costo calculado con tarifas configuradas. No es factura conciliada.' };
    return { costo: costo, tipo: 'estimado', motivo: 'Caché no informada por la API: estimación conservadora sin descuento de caché (no se afirma caché medida = 0). No es factura conciliada.' };
  }

  // Reserva previa: entrada contada a tarifa normal (sin presumir caché) + salida máxima permitida.
  function reservaLlamada(p) {
    const tokens = (p.tokens_conteo * p.t.entrada + p.max_salida * p.t.salida) / 1000000;
    const herramienta = (p.busquedas_max || 0) * (p.cargo_busqueda || 0);
    const contenido = (p.tokens_contenido_supuesto || 0) * p.t.entrada / 1000000;
    return { tokens: tokens, herramienta: herramienta, contenido: contenido, total: tokens + herramienta + contenido };
  }

  // Estado del presupuesto del caso a partir de las filas originales de rh_costos.
  function estadoPresupuesto(filas) {
    const gen = (filas || []).filter((f) => f && f.tipo_registro === 'generacion');
    let contabilizado = 0; let pendiente = 0; let sinCota = 0;
    gen.forEach((f) => {
      const ec = String(f.estado_conciliacion || '');
      if ((ec === 'calculado' || ec === 'estimado' || ec === 'conciliado') && esNum(f.costo_usd)) contabilizado += f.costo_usd;
      else if (esNum(f.costo_reservado_usd)) pendiente += f.costo_reservado_usd;
      else sinCota += 1;
    });
    return { intentos: gen.length, contabilizado: contabilizado, pendiente: pendiente, sin_cota: sinCota };
  }

  function evaluarAutorizacion(est, reserva, cfg) {
    const motivos = [];
    if (cfg.max_llamadas > 0 && est.intentos + 1 > cfg.max_llamadas) motivos.push('MAX_LLAMADAS alcanzado (' + est.intentos + ' intentos de generación de ' + cfg.max_llamadas + ')');
    if (est.sin_cota > 0) motivos.push(est.sin_cota + ' llamada(s) previa(s) con consumo desconocido y sin reserva cuantificada');
    if (!(cfg.tope_usd_caso > 0)) motivos.push('TOPE_USD_CASO no configurado (vacío no es ilimitado)');
    if (reserva === null) motivos.push('Sin reserva calculable');
    else {
      const total = est.contabilizado + est.pendiente + reserva.total;
      if (total > cfg.tope_usd_caso) motivos.push('Presupuesto insuficiente: contabilizado ' + est.contabilizado + ' + reservas pendientes ' + est.pendiente + ' + nueva reserva ' + reserva.total + ' = ' + total + ' USD > TOPE_USD_CASO ' + cfg.tope_usd_caso);
    }
    return motivos;
  }

  function mensajeErrorApi(status, body, modelo, fase) {
    const e = (body && body.error) || {};
    const msg = String(e.message || (typeof body === 'string' ? body : '') || '').slice(0, 300);
    const code = String(e.code || '');
    if (status === 404 || code === 'model_not_found' || /model/i.test(msg) && /(not exist|not found|does not have access|no access)/i.test(msg)) {
      return 'El modelo ' + modelo + ' no está disponible para la credencial o cuenta (' + fase + ', HTTP ' + status + (code ? ', ' + code : '') + '): ' + msg + '. No se sustituye por otro modelo.';
    }
    return 'Error de API en ' + fase + ' (HTTP ' + status + (code ? ', ' + code : '') + '): ' + msg;
  }

  // Extrae el texto final de una respuesta; solo 'completed' libera contenido.
  function extraerTexto(resp) {
    const r = { status: resp && resp.status ? String(resp.status) : null, texto: null, motivo: '' };
    if (!resp || typeof resp !== 'object') { r.motivo = 'Respuesta vacía'; return r; }
    if (r.status !== 'completed') {
      const det = resp.incomplete_details && resp.incomplete_details.reason ? ' (' + resp.incomplete_details.reason + ')' : '';
      r.motivo = 'Respuesta no completada: status ' + r.status + det;
      return r;
    }
    const msgs = (Array.isArray(resp.output) ? resp.output : []).filter((o) => o && o.type === 'message');
    const partes = [];
    msgs.forEach((m) => (m.content || []).forEach((c) => { if (c && c.type === 'output_text' && typeof c.text === 'string') partes.push(c.text); }));
    if (!partes.length) { r.motivo = 'Sin texto de salida'; return r; }
    r.texto = partes.join('\n');
    return r;
  }

  function hostPermitido(u, permitidos) {
    try { const x = new URL(String(u)); const h = x.hostname.toLowerCase(); return x.protocol === 'https:' && permitidos.some((d) => h === d || h.endsWith('.' + d)); } catch (e) { return false; }
  }
  function normUrl(u) {
    try { const x = new URL(String(u)); return x.hostname.toLowerCase().replace(/^www[.]/, '') + x.pathname.replace(/[/]+$/, ''); } catch (e) { return null; }
  }

  // Evidencia de búsqueda desde los metadatos devueltos (web_search_call y anotaciones), no desde el texto.
  function extraerBusqueda(resp, permitidos) {
    const out = resp && Array.isArray(resp.output) ? resp.output : [];
    const llamadas = out.filter((o) => o && o.type === 'web_search_call');
    const sinAccion = llamadas.filter((c) => !c.action || !c.action.type).length;
    const cobrables = llamadas.filter((c) => !c.action || !c.action.type || c.action.type === 'search').length;
    const completadas = llamadas.filter((c) => c.status === 'completed').length;
    const fuentes = [];
    llamadas.forEach((c) => { const ss = c.action && Array.isArray(c.action.sources) ? c.action.sources : []; ss.forEach((s) => { if (s && s.url) fuentes.push(String(s.url)); }); });
    const anot = [];
    out.filter((o) => o && o.type === 'message').forEach((m) => (m.content || []).forEach((p) => (p.annotations || []).forEach((a) => { if (a && a.type === 'url_citation' && a.url) anot.push({ url: String(a.url), title: String(a.title || '') }); })));
    const setFuentes = new Set(fuentes.map(normUrl).filter(Boolean));
    const recuperadasPermitidas = unicos(fuentes.filter((u) => hostPermitido(u, permitidos)));
    const ajenas = unicos(fuentes.filter((u) => !hostPermitido(u, permitidos)));
    const citasVerificadas = unicos(anot.filter((a) => hostPermitido(a.url, permitidos) && setFuentes.has(normUrl(a.url))).map((a) => a.url));
    const citasNoVerificadas = unicos(anot.map((a) => a.url).filter((u) => citasVerificadas.indexOf(u) < 0));
    const mostrar = citasVerificadas.length ? citasVerificadas : recuperadasPermitidas;
    return {
      llamadas_observadas: llamadas.length,
      busquedas_cobrables: cobrables,
      llamadas_sin_accion: sinAccion,
      llamadas_completadas: completadas,
      ids: llamadas.map((c) => String(c.id || '')),
      fuentes_recuperadas: unicos(fuentes),
