    if (typeof o.validado !== 'boolean') e.push('validado no es booleano');
    if (!esListaTxt(o.correcciones)) e.push('correcciones no es lista de textos');
    if (!esListaTxt(o.observaciones)) e.push('observaciones no es lista de textos');
    if (e.length) return e;
    const concretas = o.correcciones.filter((c) => c.trim().length >= 8);
    if (o.validado === true && o.correcciones.length > 0) e.push('Contradicción: validado=true con correcciones no vacías');
    if (o.validado === false && concretas.length === 0) e.push('Contradicción: validado=false sin una corrección concreta');
    return e;
