const restante = (cfg.timeout_ms || 0) - (Date.now() - (L.inicio_ms_caso || Date.now()));
return [{ json: { cuerpo_conteo: L.body ? RH.cuerpoConteo(L.body) : {}, errores_solicitud: errores, timeout_conteo_ms: Math.max(1000, Math.min(cfg.timeout_conteo_ms || 30000, restante)) } }];

